{
  "statement": {
    "index": 1,
    "modal": "Must",
    "text": "judge-jev MUST obtain records through Raptor's query interface."
  },
  "record": {
    "id": "REQ-JEV-0001",
    "title": "Records come from Raptor",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-07",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "",
      "statements": [
        {
          "modal": "Must",
          "text": "judge-jev MUST obtain records through Raptor's query interface."
        },
        {
          "modal": "MustNot",
          "text": "judge-jev MUST NOT parse record Markdown itself."
        },
        {
          "modal": "MustNot",
          "text": "judge-jev MUST NOT run SQL (Structured Query Language) against the record\nstore itself."
        }
      ]
    },
    "rationale": "Raptor owns the schema and every conversion; the Raptor team can change\nthem and notify judge-jev without breaking it.",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "judge-jev contains no Markdown record parser and no SQL statement.",
          "checked": false
        }
      ],
