    "id": "REQ-JEV-0207",
    "title": "Location syntax",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-08",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "",
      "statements": [
        {
          "modal": "Must",
          "text": "A location MUST take one of three forms: `path`, `path#Heading` or\n`path::Symbol`."
        },
        {
          "modal": "Must",
          "text": "A `path` location MUST select the whole file."
        },
        {
          "modal": "Must",
          "text": "A `path#Heading` location MUST select a Markdown section, from the\nheading to the next heading of the same or higher level."
        },
        {
          "modal": "Must",
          "text": "A `path::Symbol` location MUST select a code symbol resolved by\nsc-agent's tree-sitter grammars."
        },
        {
          "modal": "Must",
          "text": "Markdown sections MUST be parsed by the same rules Raptor uses for the\nsame file."
        },
        {
          "modal": "MustNot",
          "text": "A location MUST NOT be a line range."
        }
      ]
    },
    "rationale": "Line ranges drift on every edit; headings and symbols survive. One\nMarkdown parsing rule keeps judge-jev and Raptor agreeing on what a\nsection is.",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "`path#Heading` selects the same text Raptor attributes to that\nheading.",
          "checked": false
        },
        {
          "text": "A heading or symbol that does not resolve is a typed error naming the\nlocation.",
          "checked": false
        }
      ],
      "test_evidence": []
    },
