{
  "statement": {
    "index": 1,
    "modal": "Must",
    "text": "`judge-jev quality` MUST accept `--dry-run`."
  },
  "record": {
    "id": "REQ-JEV-0208",
    "title": "Dry run audits the composed request",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-08",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "",
      "statements": [
        {
          "modal": "Must",
          "text": "`judge-jev quality` MUST accept `--dry-run`."
        },
        {
          "modal": "Must",
          "text": "`judge-jev check` MUST accept `--dry-run`."
        },
        {
          "modal": "Must",
          "text": "A dry run MUST compose every request without calling Jev."
        },
        {
          "modal": "Must",
          "text": "Each dry-run entry MUST report the record id."
        },
        {
          "modal": "Must",
          "text": "Each dry-run entry MUST report the record's Raptor source."
        },
        {
          "modal": "Must",
          "text": "Each dry-run entry MUST report the resolved location as its path, section\nor symbol."
        },
        {
          "modal": "Must",
          "text": "Each dry-run entry MUST report the digest of the location's selected\ntext."
        },
        {
          "modal": "Must",
          "text": "Each dry-run entry MUST report the mode."
        },
        {
          "modal": "Must",
          "text": "Each dry-run entry MUST report the question set as its shipped id or its\noverride path."
        },
        {
          "modal": "Must",
          "text": "In `task` mode, each dry-run entry MUST report the vars file."
        },
        {
          "modal": "Must",
          "text": "In `task` mode, each dry-run entry MUST report the rendered text."
        },
        {
          "modal": "Must",
          "text": "Each dry-run entry MUST report the full composed request."
        },
        {
          "modal": "Must",
          "text": "Each dry-run entry MUST report the composed request's size against the\nrequest limit."
        },
        {
          "modal": "Must",
          "text": "For `quality`, the dry run MUST report the decision tree."
        },
        {
          "modal": "Must",
          "text": "For `quality`, the dry run MUST report the composed wave-1 request."
        },
        {
          "modal": "Must",
          "text": "A dry run MUST fail with a typed error on anything that would make the\nlive request wrong: an unresolved record or location, a render failure,\nor an oversize request."
        }
      ]
    },
    "rationale": "The caller must know the prompt will be built correctly before any text\nleaves the machine. A `quality` dry run stops at wave 1 because later\nwaves depend on live answers.",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "A dry run makes no network call and reports one entry per request a\nlive run would send.",
          "checked": false
        },
        {
          "text": "A dry run over a task location with a missing variable fails naming\nthe variable.",
          "checked": false
        }
      ],
      "test_evidence": []
    },
