{
  "statement": {
    "index": 1,
    "modal": "Must",
    "text": "`judge-jev quality` MUST take one or more record ids."
  },
  "record": {
    "id": "REQ-JEV-0209",
    "title": "Record quality command",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-08",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "",
      "statements": [
        {
          "modal": "Must",
          "text": "`judge-jev quality` MUST take one or more record ids."
        },
        {
          "modal": "Must",
          "text": "`judge-jev quality` MUST take each record id with one record-kind flag:\n`--req` (requirement), `--adr` (architecture decision record) or `--nfr`\n(non-functional requirement)."
        },
        {
          "modal": "Must",
          "text": "Every record-kind flag of `judge-jev quality` MUST be repeatable."
        },
        {
          "modal": "Must",
          "text": "`judge-jev quality` MUST judge each record with its kind's quality\ndecision tree (REQ-JEV-0101)."
        },
        {
          "modal": "Must",
          "text": "All records of one `judge-jev quality` invocation MUST be logged under\none run name."
        }
      ]
    },
    "rationale": "Quality and compliance are separate questions about separate inputs. One\nrun name per invocation groups a measurement over many records in the\nlog.",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "Every request `judge-jev quality --req <id>` sends carries only the\nrecord and questions from the REQ quality tree.",
          "checked": false
        }
      ],
