      "text": "",
      "statements": [
        {
          "modal": "Must",
          "text": "`judge-jev doctor` MUST validate every tree in the scope against its\nschema."
        },
        {
          "modal": "Must",
          "text": "`judge-jev doctor` MUST validate every question set in the scope against\nits schema."
